 private PlatformApi api;private LobbyUi skin;private LinearLayout body;private TextView status;private JSONObject room,queueFacts;private String uid="",code="";private int seats=6,pollErrors;private boolean busy,queued,foreground,launched;private final Handler ui=new Handler(Looper.getMainLooper());private final ExecutorService io=Executors.newSingleThreadExecutor();
