 @Override public void onResume(){super.onResume();foreground=true;api=new PlatformApi(this);if(launched){launched=false;room=null;code="";queued=false;}if(!api.signedIn()){home();return;}work(()->api.call("GET","/me",null),d->{uid=d.getJSONObject("user").getString("id");String restore=getIntent().getStringExtra("restore_code");getIntent().removeExtra("restore_code");if(restore!=null){code=restore;work(()->api.call("GET","/expedition/rooms/"+code,null),this::accept);}else work(()->api.call("GET","/expedition/match",null),this::accept);});}
