 private void work(Job task,Done done){if(busy||isFinishing())return;busy=true;status.setText(com.xenris.liquidwarsos.BattleText.t("正在连接…","Connecting…"));io.execute(()->{try{if(!api.signedIn()){JSONObject identity=api.ensurePlayer();uid=identity.getJSONObject("user").getString("id");}JSONObject value=task.run();ui.post(()->{busy=false;if(isFinishing()||isDestroyed())return;try{pollErrors=0;done.run(value);status.setText(api.origin.equals(PlatformApi.ORIGIN)?com.xenris.liquidwarsos.BattleText.t("游客可玩 · 房主模拟 · 等待60秒补电脑","Guests welcome · Host simulation · AI fills after 60s"):com.xenris.liquidwarsos.BattleText.t("隔离本地服务 · 不影响公网账号与数据","Isolated local server · No public accounts or data affected"));}catch(Exception error){status.setText(error.getMessage());}schedule();});}catch(Exception error){ui.post(()->{busy=false;if(isFinishing()||isDestroyed())return;status.setText(error.getMessage());if(++pollErrors==3){button(body,com.xenris.liquidwarsos.BattleText.t("重试连接","Retry connection"),true,()->{pollErrors=0;poll.run();});button(body,com.xenris.liquidwarsos.BattleText.t("返回主菜单（断线席位自动过期）","Main menu (disconnected seats expire)"),false,this::finish);}schedule();});}});}
 private void schedule(){ui.removeCallbacks(poll);if(pollErrors<3&&foreground&&!launched&&(queued||!code.isEmpty()))ui.postDelayed(poll,2000);}
 private JSONObject hello()throws JSONException{return PlatformApi.object("game_id",PlatformApi.GAME,"protocol",193,"build",BuildConfig.VERSION_CODE,"seats",seats);}
